/**
 * Next per-project issue number. Archived issues keep their number, so the
 * max is taken over every row rather than the live ones. Purged issues are
 * gone from `issues`, so the high-water mark recorded at insert time is
 * consulted as well — a purged number is never handed out again.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const db = getDb();
  const row = db
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  const mark = db
    .select({ value: projectIssueNumbers.lastNumber })
    .from(projectIssueNumbers)
    .where(
      and(
        orgPredicate(projectIssueNumbers.orgId, orgId),
        eq(projectIssueNumbers.projectId, projectId),
      ),
    )
    .get();
  return Math.max(row?.value ?? 0, mark?.value ?? 0) + 1;
}

