/**
 * Archived issues whose restore window closed at or before `cutoff`, in id
 * order. The sweep pages through them with `afterId` so a large workspace is
 * still covered in full.
 */
export async function listExpiredIssues(
  orgId: OrgId,
  cutoff: IsoTimestamp,
  page: { afterId: string | null; limit: number },
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          isNotNull(issues.archivedAt),
          lte(issues.archivedAt, cutoff),
          page.afterId === null ? undefined : gt(issues.id, page.afterId),
        ),
      ),
    )
    .orderBy(issues.id)
    .limit(page.limit)
    .all();

  return rows.map((row) => toIssue(row));
}

/**
 * Deletes an issue together with its label links, comments and attachments,
 * in one transaction. Search documents and storage accounting are the caller's
 * concern — they need the rows before they disappear.
 */
export async function purgeIssue(orgId: OrgId, issueId: IssueId): Promise<void> {
  getDb().transaction((tx) => {
    tx.delete(issueLabels)
