/**
 * Permanently removes rows archived longer ago than the plan's `retentionDays`.
 *
 * Must call (do not reimplement): getPlanLimits, isArchived
 */
import { getPlanLimits } from "@/config/plan-limits";
import { createLogger } from "@/lib/logger";
import { isArchived } from "@/lib/soft-delete";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId } from "@/types/common";
import type { Issue } from "@/types/issue";

const ORG_BATCH = 25;
const PAGE_SIZE = 100;
const MS_PER_DAY = 24 * 60 * 60 * 1000;
const BYTES_PER_MB = 1024 * 1024;

const logger = createLogger("cleanup-archived-job");

/**
 * The retention sweep. Archived issues are restorable for as long as the plan
 * promises and no longer: the cut-off comes from `retentionDays`, so an
 * enterprise tenant keeps years of history where a free one keeps a month.
 *
 * Once an issue is past the cut-off it is purged for good — the row, its
 * labels, comments and attachments, their search documents, and the storage
 * the attachments were counted for. The issue number is not released: the
 * project's high-water mark keeps it from being handed out again. Audit rows
 * past the window are purged as before.
 */
export async function runCleanupArchivedJob(now: Date): Promise<JobResult> {
  return runJob("cleanup-archived", async (result) => {
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const org = await orgRepo.findOrgById(orgId);
      if (!org) continue;

      const { retentionDays } = getPlanLimits(org.plan);
      const cutoff = toIsoTimestamp(
        new Date(now.getTime() - retentionDays * MS_PER_DAY),
      );

      let afterId: string | null = null;
      for (;;) {
        const expired: readonly Issue[] = await issueRepo.listExpiredIssues(
          orgId,
          cutoff,
          { afterId, limit: PAGE_SIZE },
        );
        if (expired.length === 0) break;

        for (const issue of expired) {
          if (!isArchived(issue)) continue;

          try {
            await purgeIssue(orgId, issue.id);
            result.processed += 1;
          } catch (error) {
            result.failed += 1;
            logger.error("issue purge failed", {
              orgId,
              issueId: issue.id,
              reason: error instanceof Error ? error.message : String(error),
            });
          }
        }

        afterId = expired[expired.length - 1]?.id ?? null;
        if (afterId === null) break;
      }

      try {
        const purged = await activityRepo.purgeActivityBefore(orgId, cutoff);
        result.processed += purged;
      } catch (error) {
        result.failed += 1;
        logger.error("activity purge failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

/**
 * Removes one expired issue and everything hanging off it. The storage the
 * attachments were counted for is given back, each one rounded up to whole MB
 * as it was when it was added. Issues are not counted in `issuesUsed` while
 * archived, so that counter is left alone.
 */
async function purgeIssue(orgId: OrgId, issueId: Issue["id"]): Promise<void> {
  const commentIds = await commentRepo.listCommentIds(orgId, issueId);
  const attachmentRows = await attachmentRepo.listAttachments(orgId, issueId);
  const storageMb = attachmentRows.reduce(
    (total, attachment) =>
      total + Math.ceil(attachment.sizeBytes / BYTES_PER_MB),
    0,
  );

  await issueRepo.purgeIssue(orgId, issueId);

  for (const commentId of commentIds) {
    await searchRepo.deleteSearchDocument(orgId, "comment", commentId);
  }
  await searchRepo.deleteSearchDocument(orgId, "issue", issueId);

  if (storageMb > 0) {
    await usageRepo.incrementUsage(orgId, { storageMbUsed: -storageMb });
  }
}

